 "content": "def transform(grid):
    """Copy the non-empty tile across regions separated by full divider lines."""
    h, w = len(grid), len(grid[0])

    def find_dividers(lines):
        # Candidate dividers are isolated, uniformly colored full lines.
        colors = []
        for line in lines:
            if line and all(x == line[0] for x in line):
                colors.append(line[0])
            else:
                colors.append(None)
        dividers = []
        for i, color in enumerate(colors):
            if color is None:
                continue
            left_same = i > 0 and colors[i - 1] == color
            right_same = i + 1 < len(colors) and colors[i + 1] == color
            if not left_same and not right_same:
                dividers.append(i)
        # Keep only divider sets yielding equal-sized, nonempty tiles.
        if not dividers:
            return []
        bounds = [-1] + dividers + [len(lines)]
        sizes = [bounds[i + 1] - bounds[i] - 1 for i in range(len(bounds) - 1)]
        if min(sizes) <= 0 or len(set(sizes)) != 1:
            return []
        return dividers

    row_divs = find_dividers(grid)
    col_divs = find_dividers([[grid[r][c] for r in range(h)] for c in range(w)])
    row_bounds = [-1] + row_divs + [h]
    col_bounds = [-1] + col_divs + [w]
    row_ranges = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_ranges = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]

    # Select the tile with the richest color content as the template.
    tiles = []
    for ri, (r0, r1) in enumerate(row_ranges):
        for ci, (c0, c1) in enumerate(col_ranges):
            tile = [row[c0:c1] for row in grid[r0:r1]]
            colors = {v for row in tile for v in row}
            tiles.append((len(colors), sum(len(set(row)) for row in tile), ri, ci, tile))
    _, _, src_ri, src_ci, source = max(tiles, key=lambda x: (x[0], x[1]))

    out = [row[:] for row in grid]
    for ri, (r0, r1) in enumerate(row_ranges):
        for ci, (c0, c1) in enumerate(col_ranges):
            if (ri, ci) == (src_ri, src_ci):
                continue
            for dr, r in enumerate(range(r0, r1)):
                for dc, c in enumerate(range(c0, c1)):
                    out[r][c] = source[dr][dc]
    return out
